// LinkedIn — Factor Combinations (LeetCode 254): every way to write n as a product of factors > 1 (excluding n itself).
public static class Factors {
    public static List<List<int>> Combinations(int n) {
        var res = new List<List<int>>();
        if (n < 4) return res;
        Build(n, 2, new List<int>(), res);
        return res;
    }

    // Factors in non-decreasing order, so each combination is produced exactly once.
    static void Build(int n, int from, List<int> path, List<List<int>> res) {
        for (int f = from; (long)f * f <= n; f++) {
            if (n % f != 0) continue;
            path.Add(f);
            res.Add(new List<int>(path) { n / f });                  // f × (n/f) completes a combination
            Build(n / f, f, path, res);                              // or keep splitting n/f
            path.RemoveAt(path.Count - 1);
        }
    }
}
```

